from pandas import Timestamp, Period
import pandas.errors

# Test the three resolution cases from the issue
for freq in ['ms', 'us', 'ns']:
    try:
        ts = Timestamp(Timestamp.min.value, unit=freq)
        per = Period(ts, freq=freq)
        probe('period_construction_freq_' + freq, 1.0)  # Success
    except pandas.errors.OutOfBoundsDatetime as e:
        probe('period_construction_freq_' + freq, 0.0)  # Exception caught
    except Exception as e:
        probe('period_construction_freq_' + freq, -1.0)  # Other exception

